import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { OrderOverrideFieldsSchema, type OrderOverrideFieldsInput } from '../objects/OrderOverrideFields'
import type { SalesDomainErrors } from '../errors'

export const OrderOverrideSchema = z.object({
	storeId: z.instance(Id),
	orderId: z.instance(Id),
	storeIntegrationExternalId: z.string(),
	fields: OrderOverrideFieldsSchema,
})

export type OrderOverrideProps = Z.infer<typeof OrderOverrideSchema>

/**
 * Deterministic id for an OrderOverride. The natural key is
 * (orderId, storeIntegrationExternalId) — the same pair that pins the
 * row in `order_overrides`. Deriving the entity id from that key keeps
 * id stable across read-rehydrate cycles even when the table doesn't
 * carry a surrogate UUID column.
 */
export function orderOverrideId(orderId: string, storeIntegrationExternalId: string): string {
	return Id.fromSeed('order_override', orderId, storeIntegrationExternalId).value
}

export class OrderOverride extends AggregateRoot<typeof OrderOverrideSchema> {
	static override schema = OrderOverrideSchema

	static create(data: {
		storeId: string
		orderId: string
		storeIntegrationExternalId: string
		fields: OrderOverrideFieldsInput
	}): OrderOverride {
		const parsed = OrderOverrideFieldsSchema.safeParse(data.fields)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		return new OrderOverride({
			id: orderOverrideId(data.orderId, data.storeIntegrationExternalId),
			...data,
			fields: parsed.data,
		})
	}

	mergeFields(patch: OrderOverrideFieldsInput): void {
		const parsed = OrderOverrideFieldsSchema.safeParse(patch)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		this.fields = { ...this.fields, ...parsed.data }
	}

	/** Replace the resolved per-line product cost (SPEC-11 ProductCostApplicationHandler output). */
	setProductCostByLine(byLine: NonNullable<OrderOverrideFieldsInput['productCostByLine']>): void {
		const next = { ...this.fields, productCostByLine: byLine }
		const parsed = OrderOverrideFieldsSchema.safeParse(next)
		if (!parsed.success) {
			throw new BaseError<SalesDomainErrors>('INVALID_ORDER_OVERRIDE_FIELDS', parsed.error.issues[0]?.message ?? 'Invalid override fields')
		}
		this.fields = parsed.data
	}
}

export interface OrderOverride extends OrderOverrideProps {}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@tenancy/middlewares/RequireStoreMember'
import { UpdateOrderOverride, UpdateOrderOverrideInputSchema, UpdateOrderOverrideOutputSchema } from '../usecases/UpdateOrderOverride'

export const UpdateOrderOverrideControllerInputSchema = z.object({
	ctx: z.object({
		user: z.object({ id: z.string() }),
		session: z.object({ storeId: z.uuid() }),
	}),
	body: UpdateOrderOverrideInputSchema.omit({ storeId: true }),
})

export const UpdateOrderOverrideControllerOutputSchema = UpdateOrderOverrideOutputSchema

@injectable()
export class UpdateOrderOverrideController extends Controller<
	typeof UpdateOrderOverrideControllerInputSchema,
	typeof UpdateOrderOverrideControllerOutputSchema
> {
	readonly path = '/orders/override'
	readonly method = 'patch' as const
	readonly description = 'Batch-update typed override fields on one or more Orders (C26 UpdateOrderOverride)'
	readonly inputSchema = UpdateOrderOverrideControllerInputSchema
	readonly outputSchema = UpdateOrderOverrideControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: UpdateOrderOverride) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			storeId: request.ctx.session.storeId,
			orderIds: request.body.orderIds,
			patch: request.body.patch,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { StoreIntegrationRepository } from '@integration/repositories'
import type { ApplicationErrors } from '@integration/errors'
import { OrderOverride } from '../entities/OrderOverride'
import { OrderOverrideFieldsSchema } from '../objects/OrderOverrideFields'
import { OrderOverrideRepository } from '../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderOverriddenEvent } from '../events'

export const UpdateOrderOverrideInputSchema = z.object({
	storeId: z.uuid(),
	orderIds: z.array(z.uuid()).min(1),
	patch: OrderOverrideFieldsSchema,
})

export const UpdateOrderOverrideOutputSchema = z.object({
	orderOverrideIds: z.array(z.uuid()),
})

/**
 * C26 UpdateOrderOverride (batch). The active `storeIntegrationExternalId`
 * is NOT part of the request — it is derived from the store's integration
 * (resolved from `storeId` via StoreIntegrationRepository). Upserts the
 * override pinned by `(orderId, storeIntegrationExternalId)` for every id
 * in `orderIds`:
 *   - if absent → create with the patch as initial fields
 *   - if present → merge the patch into existing fields (preserves
 *     non-supplied keys; spec rule "partial update on typed fields")
 *
 * No-op per-order: when the patch changes nothing for that id, the id
 * is still included in `orderOverrideIds` (the existing entity id) but
 * no event is emitted for it.
 *
 * Emits one OrderOverriddenEvent per changed order with the full entity
 * snapshot (SPEC-14). A separate handler in this BC republishes each as
 * the cross-BC `integration.shared.order.overridden` integration event.
 */
@injectable()
export class UpdateOrderOverride extends Handler<typeof UpdateOrderOverrideInputSchema, typeof UpdateOrderOverrideOutputSchema> {
	readonly name = 'update_order_override' as const
	readonly inputSchema = UpdateOrderOverrideInputSchema
	readonly outputSchema = UpdateOrderOverrideOutputSchema

	constructor(
		private readonly overrides: OrderOverrideRepository,
		private readonly storeIntegrations: StoreIntegrationRepository,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const storeIntegrationExternalId = await this.resolveExternalId(input.storeId, tx)

			const orderOverrideIds: string[] = []

			for (const orderId of input.orderIds) {
				const id = await this.applyOne(orderId, storeIntegrationExternalId, input, tx)
				orderOverrideIds.push(id)
			}

			return { orderOverrideIds }
		})
	}

	/**
	 * Derive the active `storeIntegrationExternalId` from the store's
	 * integration. The override pin speaks the provider's vocabulary
	 * (externalId), but the request only carries the storeId — so we
	 * resolve the store's integration here. A store with no integration
	 * cannot pin an override → STORE_INTEGRATION_NOT_FOUND.
	 */
	private async resolveExternalId(storeId: string, tx: Transaction): Promise<string> {
		const integrations = await this.storeIntegrations.findByStoreId(storeId, tx)
		const integration = integrations[0]
		if (!integration) {
			throw new BaseError<ApplicationErrors>('STORE_INTEGRATION_NOT_FOUND')
		}
		return integration.externalId
	}

	private async applyOne(orderId: string, storeIntegrationExternalId: string, input: this['input'], tx: Transaction): Promise<string> {
		const existing = await this.overrides.findByPin(orderId, storeIntegrationExternalId, tx)

		let entity: OrderOverride

		if (existing) {
			const fieldsBefore = JSON.stringify(existing.fields)
			existing.mergeFields(input.patch)
			const fieldsAfter = JSON.stringify(existing.fields)
			// No-op: patch changed nothing — skip save and event emission.
			if (fieldsBefore === fieldsAfter) {
				return existing.id.value
			}
			entity = existing
		} else {
			entity = OrderOverride.create({
				storeId: input.storeId,
				orderId,
				storeIntegrationExternalId,
				fields: input.patch,
			})
		}

		await this.overrides.save(entity, tx)

		await this.domainEventRepository.save(
			new OrderOverriddenEvent({
				entityId: entity.id.value,
				ownerId: entity.storeId.value,
				payload: {
					orderId: entity.orderId.value,
					storeId: entity.storeId.value,
					storeIntegrationExternalId: entity.storeIntegrationExternalId,
					entity: {
						orderId: entity.orderId.value,
						storeId: entity.storeId.value,
						storeIntegrationExternalId: entity.storeIntegrationExternalId,
						fields: entity.fields,
					},
				},
			}),
			tx,
		)

		return entity.id.value
	}
}

import { Repository } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { OrderOverride } from '../../entities/OrderOverride'

export abstract class OrderOverrideRepository extends Repository<OrderOverride> {
	/** Find by composite PK (orderId + storeIntegrationExternalId). Returns undefined when not found. */
	abstract findByPin(orderId: string, storeIntegrationExternalId: string, tx?: Transaction): Promise<OrderOverride | undefined>

	abstract override save(entity: OrderOverride, tx?: Transaction): Promise<OrderOverride>
	abstract override delete(id: string, tx?: Transaction): Promise<void>
}

// Package shared exposes the framework fx.Module that wires every
// context-agnostic infrastructure service. Bounded contexts compose
// this with their own modules in their app's fx.New() call.
package shared

import (
	"context"
	stdsql "database/sql"
	"fmt"
	"log/slog"
	"net/http"

	"template/core-go/config"
	"template/core-go/db/sql"
	"template/core-go/middleware"
	"template/core-go/repositories"
	"template/core-go/services/httprouter"
	"template/core-go/services/mediator"
	"template/core-go/services/outbox"
	"template/core-go/services/tsclient"
	"template/core-go/services/unitofwork"
	"template/core-go/types"

	"go.uber.org/fx"
)

var Module = fx.Module("shared",
	// Config
	fx.Provide(config.Load),

	// Database
	fx.Provide(sql.NewPostgresDB),

	// Infrastructure
	fx.Provide(fx.Annotate(unitofwork.NewNoopUnitOfWork, fx.As(new(unitofwork.UnitOfWork)))),
	fx.Provide(fx.Annotate(mediator.NewRedisExternalMediator, fx.As(new(mediator.ExternalMediator)))),

	// Internal Mediator (domain events via channels)
	fx.Provide(fx.Annotate(mediator.NewChannelMediator, fx.As(new(mediator.InternalMediator)))),

	// Domain Event Repository (dual-writes to events + outbox)
	fx.Provide(fx.Annotate(
		repositories.NewPgDomainEventRepository,
		fx.As(new(repositories.DomainEventRepository)),
	)),

	// Outbox Dispatcher (polls outbox → dispatches to InternalMediator)
	fx.Provide(outbox.NewOutboxDispatcher),

	// TS API client (Go→TS, service-to-service with x-internal-service-key)
	fx.Provide(tsclient.NewClient),

	// HTTP Router
	fx.Provide(httprouter.NewHttpRouter),

	// Lifecycle hooks
	fx.Invoke(registerMiddlewares),
	fx.Invoke(
		fx.Annotate(
			registerControllers,
			fx.ParamTags(``, `group:"controllers"`),
		),
	),
	fx.Invoke(func(lc fx.Lifecycle, em mediator.ExternalMediator, ob *outbox.OutboxDispatcher) {
		lc.Append(fx.Hook{
			OnStart: func(ctx context.Context) error {
				if err := em.Start(ctx); err != nil {
					return err
				}
				ob.Start(ctx)
				return nil
			},
			OnStop: func(ctx context.Context) error {
				ob.Stop()
				return em.Stop(ctx)
			},
		})
	}),
)

func registerMiddlewares(router *httprouter.HttpRouter, cfg *config.Config, db *stdsql.DB) {
	router.Use(middleware.Recovery)
	router.Use(middleware.Logging)
	// Auth middlewares (session, api-key) are domain decisions, not framework
	// defaults — let each app wire them in its own fx module if needed.
}

func registerControllers(router *httprouter.HttpRouter, controllers []types.Controller) {
	router.RegisterControllers(controllers)
}

// StartHTTPServer is an fx.Invoke target that starts the HTTP server
// and registers a graceful-shutdown lifecycle hook.
// Usage: fx.Invoke(shared.StartHTTPServer)
func StartHTTPServer(lc fx.Lifecycle, router *httprouter.HttpRouter, cfg *config.Config) {
	addr := fmt.Sprintf(":%s", cfg.Port)
	srv := &http.Server{
		Addr:    addr,
		Handler: router.Handler(),
	}

	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			slog.Info("http server starting", "addr", addr)
			go func() {
				if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
					slog.Error("http server error", "error", err)
				}
			}()
			return nil
		},
		OnStop: func(ctx context.Context) error {
			slog.Info("http server stopping")
			return srv.Shutdown(ctx)
		},
	})
}

// cmd/api — api-go entry point.
// Bootstraps all bounded-context modules via fx.New.
package main

import (
	"log/slog"
	"os"
	"time"

	"template/api-go/internal/integrations"
	"template/api-go/internal/sync"
	"template/api-go/internal/webhooks"
	shared "template/core-go"

	"go.uber.org/fx"
)

func main() {
	slog.SetDefault(slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{
		Level: slog.LevelDebug,
	})))

	fx.New(
		fx.StopTimeout(30*time.Second),

		// Shared infrastructure: DB, mediators, outbox dispatcher, HTTP router.
		shared.Module,

		// Bounded contexts.
		sync.Module,
		integrations.Module,
		webhooks.Module,

		// Start the HTTP server.
		fx.Invoke(shared.StartHTTPServer),
	).Run()
}

package types

import "context"

// Handler represents a use case handler with typed input/output.
// Each use case defines its own Input/Output structs with validate tags
// and a concrete handler struct that implements this interface.
type Handler[I any, O any] interface {
	Name() string
	Execute(ctx context.Context, input I) (O, error)
}

// Package sync provides the fx.Module for the sync bounded context.
// Owns POST /sync (back-compat), POST /sync/jobs, POST /sync/jobs/{id}/execute,
// GET /sync/jobs, GET /sync/jobs/{id}, POST /sync/jobs/{id}/cancel,
// POST /sync/jobs/{id}/execute-async.
//
// fx wiring layered by responsibility:
//
//	pipelines.Factory ← []pipelines.Pipeline group
//	executor.Executor ← pipelines.Factory + syncjob.SyncJobRepository + mediator.InternalMediator + DomainEventRepository
//	usecases.StartSync  ← syncjob.SyncJobRepository + unitofwork.UnitOfWork
//	usecases.ExecuteSync ← executor.Executor
//	usecases.GetSyncStatus ← syncjob.SyncJobRepository
//	usecases.ListSyncJobs  ← syncjob.SyncJobRepository
//	usecases.CancelSync    ← syncjob.SyncJobRepository
//	usecases.AsyncExecuteSync ← executor.Executor (AsyncExecutor interface)
//	controllers.SyncController ← usecases.StartSync + usecases.ExecuteSync
//
// Handlers (OrderUpdatedHandler, ProductUpdatedHandler, ProductVariantUpdatedHandler)
// are provided into the DI graph AND registered with the mediator via fx.Invoke.
// This ensures that executor.syncPublisher.Dispatch(...) reaches the handlers
// and persists entities + wire events before the HTTP response.
//
// Pipelines fed into the `group:"pipelines"` slot:
//   - Shopify orders + products + transactions (real impls)
//   - META × {BUSINESS_ACCOUNTS, AD_ACCOUNTS, CAMPAIGNS, MARKETING_METRICS} (real impls)
//   - TIKTOK × {BUSINESS_ACCOUNTS, AD_ACCOUNTS, CAMPAIGNS, MARKETING_METRICS} (real impls)
//   - GOOGLE_ADS × {BUSINESS_ACCOUNTS, AD_ACCOUNTS, CAMPAIGNS, MARKETING_METRICS} (real impls)
//   - NUVEM_SHOP × orders+products (real implementations)
package sync

import (
	"context"
	"database/sql"
	"log/slog"
	"net/http"

	_ "template/api-go/internal/sync/errors" // registers HTTP status codes via init()

	"template/api-go/internal/sync/controllers"
	"template/api-go/internal/sync/enums"
	"template/api-go/internal/sync/handlers"
	repoad "template/api-go/internal/sync/repositories/ad"
	repoadaccount "template/api-go/internal/sync/repositories/adaccount"
	repoadset "template/api-go/internal/sync/repositories/adset"
	repoadspend "template/api-go/internal/sync/repositories/adspend"
	repobusinessaccount "template/api-go/internal/sync/repositories/businessaccount"
	repocampaign "template/api-go/internal/sync/repositories/campaign"
	pixelrepo "template/api-go/internal/sync/repositories/pixel"
	"template/api-go/internal/sync/repositories/syncjob"
	"template/api-go/internal/sync/services/credentials"
	"template/api-go/internal/sync/services/executor"
	"template/api-go/internal/sync/services/pipelines"
	facebookpipelines "template/api-go/internal/sync/services/pipelines/facebook"
	googlepipelines "template/api-go/internal/sync/services/pipelines/google"
	nuvemshoppipelines "template/api-go/internal/sync/services/pipelines/nuvemshop"
	shopifypipelines "template/api-go/internal/sync/services/pipelines/shopify"
	tiktokpipelines "template/api-go/internal/sync/services/pipelines/tiktok"
	nuvemshopsvc "template/api-go/internal/sync/services/nuvemshop"
	shopifysvc "template/api-go/internal/sync/services/shopify"
	storagead "template/api-go/internal/sync/storage/ad"
	storageadaccount "template/api-go/internal/sync/storage/adaccount"
	storageadset "template/api-go/internal/sync/storage/adset"
	storageadspend "template/api-go/internal/sync/storage/adspend"
	storagebusinessaccount "template/api-go/internal/sync/storage/businessaccount"
	storagecampaign "template/api-go/internal/sync/storage/campaign"
	"template/api-go/internal/sync/storage/order"
	storagepixel "template/api-go/internal/sync/storage/pixel"
	"template/api-go/internal/sync/storage/product"
	productvariant "template/api-go/internal/sync/storage/product_variant"
	"template/api-go/internal/sync/storage/transaction"
	"template/api-go/internal/sync/services/pixelthrottle"
	"template/api-go/internal/sync/services/saleschannel"
	"template/api-go/internal/sync/usecases"
	"template/core-go/config"
	corerepos "template/core-go/repositories"
	coremediator "template/core-go/services/mediator"
	"template/core-go/services/unitofwork"
	tsclientgen "template/client-go/pkg/typescript"
	"template/core-go/types"
	wire "template/contracts-go/wire"

	"github.com/redis/go-redis/v9"
	"go.uber.org/fx"
)

var Module = fx.Module("sync",
	// --- Shared HTTP client ---
	fx.Provide(func() *http.Client { return &http.Client{} }),

	// --- Shopify HTTP client + normalizers ---
	fx.Provide(shopifysvc.NewShopifyHTTPClient),
	fx.Provide(func(c *shopifysvc.ShopifyHTTPClient) pipelines.ShopifyClient { return c }),
	fx.Provide(func() shopifysvc.OrderNormalizer { return shopifysvc.NewOrdersNormalizer() }),
	fx.Provide(func() shopifysvc.ProductNormalizer { return shopifysvc.NewProductsNormalizer() }),
	fx.Provide(func() shopifysvc.ProductVariantNormalizer { return shopifysvc.NewProductVariantsNormalizer() }),
	fx.Provide(func() shopifysvc.TransactionNormalizer { return shopifysvc.NewTransactionsNormalizer() }),

	// --- Storage constructors (consumed by handlers) ---
	// All four storages now require a UnitOfWork and DomainEventRepository
	// so that Save() does the bulk upsert + outbox insert in one transaction.
	fx.Provide(func(
		db *sql.DB,
		uow unitofwork.UnitOfWork,
		eventRepo corerepos.DomainEventRepository,
	) *order.PgOrderStorage {
		return order.NewPgOrderStorage(db, uow, eventRepo)
	}),
	fx.Provide(func(
		db *sql.DB,
		uow unitofwork.UnitOfWork,
		eventRepo corerepos.DomainEventRepository,
	) *product.PgProductStorage {
		return product.NewPgProductStorage(db, uow, eventRepo)
	}),
	fx.Provide(func(
		db *sql.DB,
		uow unitofwork.UnitOfWork,
		eventRepo corerepos.DomainEventRepository,
	) *productvariant.PgProductVariantStorage {
		return productvariant.NewPgProductVariantStorage(db, uow, eventRepo)
	}),
	fx.Provide(func(
		db *sql.DB,
		uow unitofwork.UnitOfWork,
		eventRepo corerepos.DomainEventRepository,
	) *transaction.PgTransactionStorage {
		return transaction.NewPgTransactionStorage(db, uow, eventRepo)
	}),
	fx.Provide(func(
		db *sql.DB,
		uow unitofwork.UnitOfWork,
		eventRepo corerepos.DomainEventRepository,
	) *storagepixel.PgPixelStorage {
		return storagepixel.NewPgPixelStorage(db, uow, eventRepo)
	}),

	// --- Sales-channel resolver (immutable storeIntegrationId → storeId mapping, cached) ---
	fx.Provide(func(db *sql.DB) *saleschannel.Resolver {
		return saleschannel.NewResolver(saleschannel.NewPgReader(db))
	}),

	// --- Marketing aggregate repositories (simple db-only constructors) ---
	fx.Provide(func(db *sql.DB) repobusinessaccount.BusinessAccountRepository {
		return repobusinessaccount.NewPgBusinessAccountRepository(db)
	}),
	fx.Provide(func(db *sql.DB) repoadaccount.AdAccountRepository {
		return repoadaccount.NewPgAdAccountRepository(db)
	}),
	fx.Provide(func(db *sql.DB) repocampaign.CampaignRepository {
		return repocampaign.NewPgCampaignRepository(db)
	}),
	fx.Provide(func(db *sql.DB) repoadset.AdSetRepository {
		return repoadset.NewPgAdSetRepository(db)
	}),
	fx.Provide(func(db *sql.DB) repoad.AdRepository {
		return repoad.NewPgAdRepository(db)
	}),
	fx.Provide(func(db *sql.DB) repoadspend.AdSpendRepository {
		return repoadspend.NewPgAdSpendRepository(db)
	}),

	// --- Marketing aggregate storages (simple channel-drain, no UoW/outbox) ---
	fx.Provide(func(repo repobusinessaccount.BusinessAccountRepository) *storagebusinessaccount.PgBusinessAccountStorage {
		return storagebusinessaccount.NewPgBusinessAccountStorage(repo)
	}),
	fx.Provide(func(repo repoadaccount.AdAccountRepository) *storageadaccount.PgAdAccountStorage {
		return storageadaccount.NewPgAdAccountStorage(repo)
	}),
	fx.Provide(func(repo repocampaign.CampaignRepository) *storagecampaign.PgCampaignStorage {
		return storagecampaign.NewPgCampaignStorage(repo)
	}),
	fx.Provide(func(repo repoadset.AdSetRepository) *storageadset.PgAdSetStorage {
		return storageadset.NewPgAdSetStorage(repo)
	}),
	fx.Provide(func(repo repoad.AdRepository) *storagead.PgAdStorage {
		return storagead.NewPgAdStorage(repo)
	}),
	fx.Provide(func(repo repoadspend.AdSpendRepository) *storageadspend.PgAdSpendStorage {
		return storageadspend.NewPgAdSpendStorage(repo)
	}),

	// --- SyncJob Postgres repository bound to the SyncJobRepository interface ---
	// The wrapper function returns the interface so fx registers it as
	// syncjob.SyncJobRepository (the type the executor + usecases expect).
	fx.Provide(func(db *sql.DB) syncjob.SyncJobRepository {
		return syncjob.NewPgSyncJobRepository(db)
	}),

	// --- Shopify pipelines registered into group:"pipelines" ---
	fx.Provide(fx.Annotate(
		shopifypipelines.NewShopifyOrdersPipeline,
		fx.As(new(pipelines.Pipeline)),
		fx.ResultTags(`group:"pipelines"`),
	)),
	fx.Provide(fx.Annotate(
		shopifypipelines.NewShopifyProductsPipeline,
		fx.As(new(pipelines.Pipeline)),
		fx.ResultTags(`group:"pipelines"`),
	)),
	fx.Provide(fx.Annotate(
		shopifypipelines.NewShopifyTransactionsPipeline,
		fx.As(new(pipelines.Pipeline)),
		fx.ResultTags(`group:"pipelines"`),
	)),

	// --- Nuvemshop HTTP client + normalizers ---
	fx.Provide(func() nuvemshopsvc.PipelineClient {
		return nuvemshopsvc.NewNuvemshopHTTPClient(nuvemshopsvc.ClientConfig{})
	}),
	fx.Provide(func() *nuvemshopsvc.OrderNormalizer { return nuvemshopsvc.NewOrderNormalizer() }),
	fx.Provide(func() *nuvemshopsvc.ProductNormalizer { return nuvemshopsvc.NewProductNormalizer() }),
	fx.Provide(func() *nuvemshopsvc.ProductVariantNormalizer { return nuvemshopsvc.NewProductVariantNormalizer() }),

	// --- Nuvemshop pipelines — real implementations ---
	fx.Provide(fx.Annotate(
		nuvemshoppipelines.NewNuvemshopOrdersPipeline,
		fx.As(new(pipelines.Pipeline)),
		fx.ResultTags(`group:"pipelines"`),
	)),
	fx.Provide(fx.Annotate(
		nuvemshoppipelines.NewNuvemshopProductsPipeline,
		fx.As(new(pipelines.Pipeline)),
		fx.ResultTags(`group:"pipelines"`),
	)),

