import type { ZodType } from 'zod'
import type { DependencyContainer } from 'tsyringe-neo'
import { container as rootContainer } from 'tsyringe-neo'
import { Router } from './Router'
import type { Controller } from './Controller'
import type { Middleware, MiddlewareClass } from './Middleware'
import { InternalMediator, ExternalMediator, Mediator } from '../services/Mediator'
import { CommandQueue } from '../services/CommandQueue'
import { autoTrace } from '../utils/Tracing'
import { registerAll, type InstanceRegistry } from './Registry'
import type { Handler } from './Handler'
import type { Projector } from './Projector'
import { tryCatch } from '../utils/TryCatch'

type Constructor<T = object> = new (...args: any[]) => T
type MiddlewareInput = Record<string, Constructor<Middleware>> | MiddlewareClass[] | []
type HandlerRecord = Record<string, new (...args: any[]) => Handler>

export interface JobDefinition {
	handler: new (...args: any[]) => Handler
	repeat: { every: number } | { pattern: string }
}

export interface BoundedContextOptions {
	name: string
	root?: boolean
	controllers: Record<string, Constructor<Controller<ZodType, ZodType>>>
	middlewares?: MiddlewareInput
	skipMiddlewares?: MiddlewareInput
	internalHandlers?: HandlerRecord
	externalHandlers?: HandlerRecord
	projectors?: Record<string, new (...args: any[]) => Projector>
	registry?: InstanceRegistry
	jobs?: JobDefinition[]
	setup?: (container: DependencyContainer) => void | Promise<void>
}

export class BoundedContext {
	private constructor(
		readonly container: DependencyContainer,
		readonly router: Router,
	) {}

	static async create(options: BoundedContextOptions): Promise<BoundedContext> {
		const container = options.root ? rootContainer : rootContainer.createChildContainer()

		if (options.registry) {
			registerAll(options.root ? container : rootContainer, options.registry.real)
		}

		autoTrace(container)

		await BoundedContext.registerHandlers(container, options)
		await BoundedContext.registerProjectors(container, options)
		await BoundedContext.registerJobs(container, options.jobs)
		await options.setup?.(container)

		const router = new Router(options.name, container, options.controllers, options.middlewares, options.skipMiddlewares)

		return new BoundedContext(container, router)
	}

	private static async registerHandlers(container: DependencyContainer, options: BoundedContextOptions): Promise<void> {
		if (!options.internalHandlers && !options.externalHandlers) return

		if (options.internalHandlers) {
			const mediator = container.resolve(InternalMediator as any) as InternalMediator
			await Mediator.register(container, mediator, options.internalHandlers)
		}

		if (options.externalHandlers) {
			const mediator = container.resolve(ExternalMediator as any) as ExternalMediator
			await Mediator.register(container, mediator, options.externalHandlers)
		}
	}

	private static async registerProjectors(container: DependencyContainer, options: BoundedContextOptions): Promise<void> {
		if (!options.projectors) return

		const mediator = container.resolve(InternalMediator as any) as InternalMediator
		let successCount = 0

		for (const [projectorName, ProjectorClass] of Object.entries(options.projectors)) {
			if (typeof ProjectorClass !== 'function' || projectorName === 'default') continue

			const result = tryCatch(() => {
				const projectorInstance = container.resolve(ProjectorClass) as Projector

				for (const eventName of projectorInstance.events) {
					// Wrap the projector as a minimal Handler-compatible object for mediator.register
					const pseudoHandler = {
						name: eventName,
						bindContainer: (_c: DependencyContainer) => pseudoHandler,
						execute: async (input: any) => {
							await projectorInstance.handle(input)
						},
					} as any
					mediator.register(pseudoHandler)
				}

				successCount++
			})

			if (!result.success) {
				console.warn(`Failed to resolve Projector ${projectorName}:`, result.error)
			}
		}

		console.log(`✅ Registered ${successCount} Projectors`)
	}

	private static async registerJobs(container: DependencyContainer, jobs?: JobDefinition[]): Promise<void> {
		if (!jobs?.length) return

		const commandQueue = container.resolve(CommandQueue as any) as CommandQueue

		for (const job of jobs) {
			const handler = container.resolve(job.handler).bindContainer(container)
			await commandQueue.registerCommandHandler(handler)
			await commandQueue.enqueueCommand(handler.name, {}, { repeat: job.repeat })
		}
	}
}

import { z, type ZodType } from 'zod'
import { setTimeout as sleep } from 'node:timers/promises'
import { container } from 'tsyringe-neo'

type BodyInit = NonNullable<ConstructorParameters<typeof Response>[0]>
import { Handler } from './Handler'
import {
	HttpControllerRequest,
	HttpControllerResponse,
	HttpMethod,
	HttpMiddlewareResponse,
	MimeTypes,
	HttpControllerError,
	HttpCookie,
	HttpStatusCode,
} from './Http'
import { Middleware, MiddlewareClass } from './Middleware'
import { BaseError } from './BaseError'
import { BaseInterfaceErrors } from '../errors/codes'
import { type AllErrors, GlobalErrorMapper } from '../utils/GlobalErrorMapper'
import { tryCatchAsync } from '../utils/TryCatch'

// Helper to extract examples from Zod schema meta
const getSchemaExamples = (schema: ZodType): unknown[] => {
	const examples = schema?.meta()?.examples as unknown[]
	return examples ?? []
}

export abstract class Controller<InputSchema extends ZodType = ZodType, OutputSchema extends ZodType = ZodType> extends Handler<
	InputSchema,
	OutputSchema
> {
	// Required properties.
	abstract readonly path: `/${string}`
	abstract readonly method: HttpMethod | HttpMethod[]
	abstract readonly description: string

	// Optional properties.
	readonly contentType: MimeTypes = MimeTypes['.json']
	readonly mockController: boolean = false
	middlewares: (Middleware | MiddlewareClass)[] = []
	skipMiddlewares: (Middleware | MiddlewareClass)[] = []

	// Base Properties
	readonly errorMapper = GlobalErrorMapper
	readonly errors: AllErrors[] = []
	readonly baseErrors: AllErrors[] = ['VALIDATION_ERROR']

	// Override input type to wrap in HTTP request
	declare readonly input: HttpControllerRequest<z.output<(typeof this)['inputSchema']>>
	// Override output type to wrap in HTTP response (allows cookies)
	// @ts-expect-error - Intentionally overriding to wrap in HTTP response with cookie support
	declare readonly output: HttpControllerResponse<z.output<(typeof this)['outputSchema']>>

	name = this.constructor.name

	/**
	 * Optional hook for mock controllers to return a custom response (e.g. with cookies).
	 * Receives the validated request. If defined and mockController is true, its return value is used instead of the schema example.
	 */
	protected getMockResponse?(
		_request: z.output<InputSchema>,
	): { status: HttpStatusCode; data: z.output<OutputSchema>; cookie?: Record<string, HttpCookie> } | undefined

	override async execute(input: unknown): Promise<this['output']> {
		const validated = this.validatedRequest(input)
		// handle() returns `this['output'] | void` (Handler base
		// signature widened so void-output handlers can return bare);
		// controllers always return a real response so the cast is
		// type-safe in practice.
		return (await this.handle({ ...(input as Record<string, unknown>), ...validated })) as this['output']
	}

	async executeController(request: HttpControllerRequest<unknown>): Promise<Response> {
		const result = await tryCatchAsync(async () => {
			const middlewareResponse = await this.executeMiddlewares(request)
			if (middlewareResponse) return middlewareResponse
			if (this.mockController) {
				await sleep(600)
				const validated = this.validatedRequest(request)
				const customMock = this.getMockResponse?.(validated as z.output<InputSchema>)
				if (customMock) {
					return this.buildResponse({
						status: customMock.status,
						data: customMock.data,
						cookie: customMock.cookie,
					})
				}
				const examples = getSchemaExamples(this.outputSchema)
				const firstOutputExample = examples[0]
				if (!firstOutputExample) throw new BaseError<BaseInterfaceErrors>('INVALID_CONTROLLER_EXAMPLES')
				return this.buildResponse({
					status: HttpStatusCode.OK,
					data: firstOutputExample,
				})
			}
			const response = await this.execute(request)
			if (response instanceof Response) return response
			return this.buildResponse(response)
		})
		if (!result.success) {
			return this.handleError(result.error)
		}
		return result.data
	}

	private async executeMiddlewares(request: HttpControllerRequest<unknown>): Promise<Response | undefined> {
		const blacklist = new Set(
			this.skipMiddlewares.map(skip => {
				if (typeof skip === 'function') return skip.name
				return skip.constructor.name
			}),
		)

		for (const middlewareOrClass of this.middlewares) {
			let middleware: Middleware
			if (typeof middlewareOrClass === 'function') {
				middleware = container.resolve(middlewareOrClass)
			} else {
				middleware = middlewareOrClass
			}

			if (blacklist.has(middleware.constructor.name)) {
				continue
			}

			const middlewareResponse = await middleware.execute(request)
			this.applyMiddlewareResponse(request, middlewareResponse)

			// If middleware returns a status, build and return the response early
			if (middlewareResponse.status) {
				return this.buildMiddlewareResponse(middlewareResponse)
			}
		}
	}

	private buildMiddlewareResponse(middlewareResponse: HttpMiddlewareResponse<unknown>): Response {
		const { status, headers, cookie } = middlewareResponse
		const response = new Response(null, { status })
		this.setResponseHeaders(response, headers)
		this.setResponseCookies(response, cookie)
		return response
	}

	private applyMiddlewareResponse(request: HttpControllerRequest<unknown>, middlewareResponse: HttpMiddlewareResponse<unknown>): void {
		const { cookie, headers } = middlewareResponse
		if (cookie) request.cookie = { ...request.cookie, ...cookie }
		if (headers) request.headers = { ...request.headers, ...this.filterUndefinedValues(headers) }
	}

	private filterUndefinedValues<T extends Record<string, unknown>>(obj: T): Partial<T> {
		return Object.fromEntries(Object.entries(obj).filter(([, value]) => value !== undefined)) as Partial<T>
	}

	private buildResponse(controllerResponse: HttpControllerResponse<z.output<ZodType>>): Response {
		const { status, data, headers, cookie } = controllerResponse
		const isVoid = data === undefined || data === null
		const body = isVoid ? null : this.serializeBody(data)
		const responseStatus = isVoid && status === HttpStatusCode.OK ? HttpStatusCode.NO_CONTENT : status
		const response = new Response(body, { status: responseStatus })
		if (!isVoid) this.setContentType(response)
		this.setResponseHeaders(response, headers)
		this.setResponseCookies(response, cookie)
		return response
	}

	private serializeBody(data: unknown): BodyInit {
		if (this.isBodyInit(data)) {
			return data as BodyInit
		}
		return JSON.stringify(data)
	}

	private isBodyInit(data: unknown): data is BodyInit {
		return (
			data !== undefined &&
			data !== null &&
			(data instanceof Blob ||
				data instanceof FormData ||
				data instanceof URLSearchParams ||
				data instanceof ReadableStream ||
				data instanceof ArrayBuffer ||
				typeof data === 'string' ||
				ArrayBuffer.isView(data))
		)
	}

	private setResponseHeaders(response: Response, headers?: Record<string, string | undefined>): void {
		if (!headers) return
		Object.entries(headers).forEach(([key, value]) => {
			if (value !== undefined) {
				response.headers.set(key, value)
			}
		})
	}

	private setResponseCookies(response: Response, cookies?: Record<string, HttpCookie>): void {
		if (!cookies) return
		Object.entries(cookies).forEach(([key, cookie]) => {
			if (cookie.value) {
				const cookieString = this.buildCookieString(key, cookie)
				response.headers.append('Set-Cookie', cookieString)
			}
		})
	}

	private buildCookieString(key: string, cookie: HttpCookie): string {
		const cookieString = `${key}=${cookie.value}`
		const attributes = this.buildCookieAttributes(cookie)
		return attributes ? `${cookieString}; ${attributes}` : cookieString
	}

	private buildCookieAttributes(cookie: HttpCookie): string {
		return Object.entries(cookie)
			.filter(([attr, value]) => attr !== 'value' && value !== undefined)
			.map(([attr, value]) => `${attr}=${value}`)
			.join('; ')
	}

	private setContentType(response: Response): void {
		if (this.contentType) {
			response.headers.set('Content-Type', this.contentType)
		}
	}

	private handleError(error: unknown): Response {
		if (error instanceof BaseError) {
			const { name, message } = error
			const status = this.errorMapper[name as AllErrors] ?? HttpStatusCode.INTERNAL_SERVER_ERROR
			throw new HttpControllerError(name, status, message)
		}
		throw error
	}
}

import { BaseInterfaceErrors, type BaseInfrastructureErrors } from '../errors/codes'
import { tryCatchAsync } from '../utils/TryCatch'
import { BaseError } from './BaseError'
import { UnitOfWorkFactory, type Transaction } from '../services/UnitOfWork/UnitOfWork'
import { z, type ZodType, type ZodIssue } from 'zod'
import type { DependencyContainer } from 'tsyringe-neo'

// Type-only imports to avoid circular dependencies
import { DomainEventRepository } from '../repositories/DomainEventRepository'
import { InternalMediator, type Mediator } from '../services/Mediator/Mediator'

export abstract class Handler<
	InputSchema extends ZodType = ZodType,
	OutputSchema extends ZodType = ZodType,
	// Default to the persistence-agnostic Transaction, NOT DrizzleClient: withTransaction
	// yields this to handlers/use cases, which pass it straight to repos. Only the Drizzle
	// repo impls narrow it to DrizzleClient. Keeps infra out of the write-side flow.
	Tx extends Transaction = Transaction,
> {
	private _container?: DependencyContainer

	abstract readonly name: string
	abstract readonly inputSchema: InputSchema
	abstract readonly outputSchema: OutputSchema
	readonly concurrency?: number

	readonly input!: z.output<(typeof this)['inputSchema']>
	readonly output!: z.output<(typeof this)['outputSchema']>

	bindContainer(container: DependencyContainer): this {
		this._container = container
		this.bindChildHandlers(this, container, new WeakSet())
		return this
	}

	private bindChildHandlers(target: object, container: DependencyContainer, visited: WeakSet<object>): void {
		if (visited.has(target)) return
		visited.add(target)

		for (const value of Object.values(target)) {
			this.visitForBinding(value, container, visited)
		}
	}

	private visitForBinding(value: unknown, container: DependencyContainer, visited: WeakSet<object>): void {
		if (!value || typeof value !== 'object') return
		if (value instanceof Handler) {
			if (!value._container) value.bindContainer(container)
			return
		}
		if (Array.isArray(value)) {
			for (const item of value) this.visitForBinding(item, container, visited)
			return
		}
		if (Object.getPrototypeOf(value) !== Object.prototype) {
			this.bindChildHandlers(value, container, visited)
		}
	}

	protected get di(): DependencyContainer {
		if (!this._container) {
			throw new BaseError<BaseInfrastructureErrors>(
				'HANDLER_NOT_BOUND',
				`${this.constructor.name} was resolved without a bound DI container. Resolve the handler via Handler.bindContainer(container) or through the DI-registered handler pipeline instead of constructing it directly.`,
			)
		}

		return this._container
	}

	// Core infrastructure — lazily resolved from the handler DI container
	protected get unitOfWorkFactory(): UnitOfWorkFactory {
		return this.di.resolve(UnitOfWorkFactory as any)
	}

	protected get domainEventRepository(): DomainEventRepository {
		return this.di.resolve(DomainEventRepository as any) as unknown as DomainEventRepository
	}

	protected get internalMediator(): Mediator {
		return this.di.resolve(InternalMediator as any) as unknown as Mediator
	}

	// `| void` lets handlers whose outputSchema resolves to z.void()
	// (e.g. RegisterFcmToken, UpdateProfile, every EventHandler
	// subclass …) return bare without a cast. TypeScript can't see
	// through the generic indirection to narrow `this['output']` to
	// `void` when outputSchema is z.void(); the union covers that
	// gap without affecting handlers that return a real shape (their
	// compiler-validated `return { … }` still satisfies
	// `this['output']`).
	protected abstract handle(input: this['input'], tx?: Tx): Promise<this['output'] | undefined>

	async execute(input: this['input'], tx?: Tx): Promise<this['output']> {
		const result = await tryCatchAsync(async () => {
			const decodedInput = this.validatedRequest(input)
			return await this.handle(decodedInput, tx)
		})
		if (!result.success) {
			throw result.error
		}
		// handle() returns `this['output'] | void`; cast back to the
		// narrower signature execute() promises. For void-outputting
		// handlers, result.data is undefined which is a valid
		// `void` instance of `this['output']`.
		return result.data as this['output']
	}

	protected async withTransaction<T>(tx: Tx | undefined, fn: (tx: Tx) => Promise<T>): Promise<T> {
		if (tx) return fn(tx)
		const uow = this.unitOfWorkFactory.create()
		return uow.transaction(async newTx => fn(newTx as Tx))
	}

	protected validatedRequest(input: unknown): this['input'] {
		const result = this.inputSchema.safeParse(input)
		if (!result.success) {
			const validationErrorString = this.getValidationErrorString(result.error.issues)
			throw new BaseError<BaseInterfaceErrors>('VALIDATION_ERROR', validationErrorString)
		}
		return result.data
	}

	protected getValidationErrorString(issues: ZodIssue[]): string {
		return issues.map(issue => this.getZodIssueMessage(issue)).join('; ')
	}

	protected getZodIssueMessage(issue: ZodIssue): string {
		const path = issue.path.join('.')
		return `${issue.message} at ${path || 'root'}`
	}
}

import { Id } from '../objects/Id'
import { ValueObject } from '../objects/ValueObject'
import { BaseError } from '../types/BaseError'
import type { BaseDomainEvent, DomainEventSchemaConstraint } from '../types/BaseDomainEvent'
import type { z, ZodObject, ZodRawShape, ZodType } from 'zod'
import type { BaseDomainErrors } from '../errors'

/** Widest accepted domain event shape — any subclass schema matching the constraint. */
type AnyDomainEvent = BaseDomainEvent<DomainEventSchemaConstraint>

export interface BaseEntityProps {
	id?: Id | string
	createdAt?: Date
	updatedAt?: Date
	version?: number
}

export abstract class BaseEntity<T extends ZodObject = ZodObject<ZodRawShape>> extends ValueObject {
	static schema?: ZodType
	private domainEvents: AnyDomainEvent[] = []

	id: Id = new Id()
	createdAt: Date = new Date()
	updatedAt: Date = new Date()
	version = 1

	constructor(props?: z.input<T> & BaseEntityProps) {
		super()
		if (!props) return

		const schema = (this.constructor as typeof BaseEntity).schema
		const result = schema?.safeParse(props)

		if (result && !result.success) {
			throw new BaseError<BaseDomainErrors>('INVALID_ENTITY', result.error.issues[0]?.message)
		}

		// Assign transformed domain props (schema applies .transform())
		Object.assign(this, result?.data ?? props)

		// Handle base entity props explicitly (id accepts string or Id)
		if (props.id != null) this.id = props.id instanceof Id ? props.id : new Id(props.id as string)
		if (props.createdAt != null) this.createdAt = props.createdAt
		if (props.updatedAt != null) this.updatedAt = props.updatedAt
		if (props.version != null) this.version = props.version
	}

	protected validate(): void {
		const schema = (this.constructor as typeof BaseEntity).schema
		if (!schema) return
		const result = schema.safeParse(this)
		if (!result.success) throw new BaseError(result.error.issues[0]!.message)
		Object.assign(this, result.data)
	}

	incrementVersion(): void {
		this.version++
		this.updatedAt = new Date()
	}

	/**
	 * Raise a domain event. Called from inside behavior methods when an
	 * aggregate transitions to a new state. Events accumulate until
	 * `pullDomainEvents()` is called (typically by a use case or handler
	 * that then persists them via `domainEventRepository.save`).
	 */
	protected addDomainEvent(event: AnyDomainEvent): void {
		this.domainEvents.push(event)
	}

	/**
	 * Drain and return all pending domain events. Clears the internal buffer.
	 * Callers iterate the returned array and persist each event via
	 * `domainEventRepository.save(event, tx)` inside the same transaction as
	 * the entity write.
	 */
	pullDomainEvents(): AnyDomainEvent[] {
		const events = this.domainEvents
		this.domainEvents = []
		return events
	}

	static transformed() {
		// biome-ignore lint/complexity/noThisInStatic: polymorphic this pattern — subclasses call BaseEntity.transformed() and `this` must resolve to the subclass constructor at runtime
		const Cls = this as unknown as { schema: ZodType; new (props: unknown): BaseEntity }
		return Cls.schema.input().transform((v: unknown) => new Cls(v))
	}
}

package httprouter

import (
	"fmt"
	"io/fs"
	"log/slog"
	"net/http"
	"strings"

	"template/core-go/config"
	"template/core-go/types"
)

const scalarHTML = `<!DOCTYPE html>
<html>
<head>
  <title>API Reference</title>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
</head>
<body>
  <script id="api-reference" data-url="/api/openapi.json"></script>
  <script src="https://cdn.jsdelivr.net/npm/@scalar/api-reference"></script>
</body>
</html>`

// HttpRouter wraps http.ServeMux and auto-registers controllers.
type HttpRouter struct {
	mux         *http.ServeMux
	version     string
	middlewares []types.Middleware
}

func NewHttpRouter(cfg *config.Config) *HttpRouter {
	return &HttpRouter{
		mux:     http.NewServeMux(),
		version: cfg.Version,
	}
}

// Use adds a global middleware applied to all routes.
func (r *HttpRouter) Use(mw types.Middleware) {
	r.middlewares = append(r.middlewares, mw)
}

// RegisterControllers registers all controllers by reading their metadata.
// Routes are built as: /api/{version}/{context}{path} (shared context has no prefix).
func (r *HttpRouter) RegisterControllers(controllers []types.Controller) {
	for _, c := range controllers {
		meta := c.Metadata()

		fullPath := "/api/" + r.version
		if meta.Context != "" {
			fullPath += "/" + meta.Context
		}
		fullPath += meta.Path

		pattern := meta.Method + " " + fullPath

		var handler http.Handler = http.HandlerFunc(c.Handle)

		// Apply controller-specific middlewares (innermost first)
		for i := len(meta.Middlewares) - 1; i >= 0; i-- {
			handler = meta.Middlewares[i](handler)
		}

		// Apply global middlewares (outermost first)
		for i := len(r.middlewares) - 1; i >= 0; i-- {
			handler = r.middlewares[i](handler)
		}

		r.mux.Handle(pattern, handler)
		slog.Info("registered route", "method", meta.Method, "path", fullPath, "description", meta.Description)
	}
}

// RegisterDocsRoutes registers /api/openapi.json and /api/docs (Scalar API Reference).
func (r *HttpRouter) RegisterDocsRoutes(openapiJSON []byte) {
	r.mux.HandleFunc("GET /api/openapi.json", func(w http.ResponseWriter, req *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.Write(openapiJSON)
	})

	r.mux.HandleFunc("GET /api/docs", func(w http.ResponseWriter, req *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		w.Write([]byte(scalarHTML))
	})

	slog.Info("registered docs routes", "openapi", "/api/openapi.json", "scalar", "/api/docs")
}

// RegisterSPA serves the frontend SPA from an embedded filesystem.
// All unmatched routes serve index.html for client-side routing.
func (r *HttpRouter) RegisterSPA(fsys fs.FS) {
	fileServer := http.FileServerFS(fsys)

	r.mux.HandleFunc("GET /", func(w http.ResponseWriter, req *http.Request) {
		name := strings.TrimPrefix(req.URL.Path, "/")
		if name != "" {
			if _, err := fs.Stat(fsys, name); err == nil {
				fileServer.ServeHTTP(w, req)
				return
			}
		}

		if strings.HasPrefix(req.URL.Path, "/api/") {
			http.NotFound(w, req)
			return
		}

		http.ServeFileFS(w, req, fsys, "index.html")
	})

	slog.Info("registered SPA (embedded)")
}

// Handler returns the underlying http.Handler for use with http.ListenAndServe.
func (r *HttpRouter) Handler() http.Handler {
	return r.mux
}

// PrintRoutes logs all registered route patterns (for debugging).
func (r *HttpRouter) PrintRoutes() {
	fmt.Println("Registered routes:")
	fmt.Println("  GET /api/openapi.json")
	fmt.Println("  GET /api/docs")
	fmt.Println("  GET / (SPA)")
}

import { Transaction } from '../services/UnitOfWork/UnitOfWork'

export abstract class Repository<T> {
	abstract save(entity: T, transaction?: Transaction): Promise<T>
	abstract delete(id: string, transaction?: Transaction): Promise<void>
}

import { HttpControllerRequest, HttpMiddlewareResponse } from './Http'

export abstract class Middleware {
	abstract execute: (request: HttpControllerRequest<unknown>) => Promise<HttpMiddlewareResponse<unknown>>
}

export type MiddlewareClass = new (...args: any[]) => Middleware

import type { ZodType } from 'zod'
import { DependencyContainer } from 'tsyringe-neo'
import { Controller } from './Controller'
import { Middleware, MiddlewareClass } from './Middleware'

type Constructor<T = object> = new (...args: any[]) => T
type MiddlewareInput = Record<string, Constructor<Middleware>> | MiddlewareClass[]

export class Router {
	path: string
	controllers?: Controller[]
	middlewares?: (Middleware | MiddlewareClass)[]
	skipMiddlewares?: (Middleware | MiddlewareClass)[]

	constructor(
		name: string,
		container: DependencyContainer,
		controllers?: Record<string, Constructor<Controller<ZodType, ZodType>>>,
		middlewares?: MiddlewareInput,
		skipMiddlewares?: MiddlewareInput,
	) {
		console.log(`\n🚀 Starting ${name} Module Router\n`)
		this.path = `/${name.trim()}`
		this.resolve(container, controllers, middlewares, skipMiddlewares)
	}

	private resolve(
		container: DependencyContainer,
		controllers?: Record<string, Constructor<Controller<ZodType, ZodType>>>,
		middlewares?: MiddlewareInput,
		skipMiddlewares?: MiddlewareInput,
	) {
		// Register controllers first
		if (controllers && Object.keys(controllers).length > 0) {
			this.registerControllers(container, controllers)
		}

		// Register middlewares and apply them to all controllers
		if (middlewares && this.hasEntries(middlewares)) {
			this.registerMiddlewares(container, middlewares)
		}

		// Register skip middlewares and propagate to controllers
		if (skipMiddlewares && this.hasEntries(skipMiddlewares)) {
			this.registerSkipMiddlewares(container, skipMiddlewares)
		}
	}

	private hasEntries(input: MiddlewareInput): boolean {
		return Array.isArray(input) ? input.length > 0 : Object.keys(input).length > 0
	}

	private registerControllers(container: DependencyContainer, controllers: Record<string, Constructor<Controller<ZodType, ZodType>>>) {
		const controllerInstances: Controller[] = []
		let successCount = 0

		for (const [controllerName, ControllerClass] of Object.entries(controllers)) {
			if (typeof ControllerClass === 'function' && controllerName !== 'default') {
				try {
					const controllerInstance = container.resolve(ControllerClass).bindContainer(container) as Controller
					controllerInstances.push(controllerInstance)
					successCount++
				} catch (error) {
					console.warn(`Failed to resolve controller ${controllerName}:`, error)
				}
			}
		}

		// Add controllers to router
		if (controllerInstances.length > 0) {
			if (!this.controllers) {
				this.controllers = []
			}
			this.controllers.push(...controllerInstances)
		}

		console.log(`✅ Registered ${successCount} Controllers`)
	}

	private registerMiddlewares(container: DependencyContainer, middlewares: MiddlewareInput) {
		const resolvedMiddlewares = this.resolveMiddlewareInstances(container, middlewares)
		if (resolvedMiddlewares.length === 0) {
			return
		}

		if (!this.middlewares) {
			this.middlewares = []
		}
		this.middlewares.push(...resolvedMiddlewares)
	}

	private registerSkipMiddlewares(container: DependencyContainer, skipMiddlewares: MiddlewareInput) {
		const resolvedSkipMiddlewares = this.resolveMiddlewareInstances(container, skipMiddlewares)
		if (resolvedSkipMiddlewares.length === 0) {
			return
		}

		if (!this.skipMiddlewares) {
			this.skipMiddlewares = []
		}
		this.skipMiddlewares.push(...resolvedSkipMiddlewares)
	}

	private resolveMiddlewareInstances(container: DependencyContainer, middlewares: MiddlewareInput): Middleware[] {
		const resolved: Middleware[] = []

		if (Array.isArray(middlewares)) {
			for (const MiddlewareClass of middlewares) {
				try {
					const middlewareInstance = container.resolve(MiddlewareClass) as Middleware
					resolved.push(middlewareInstance)
				} catch (error) {
					console.warn(`Failed to resolve middleware ${MiddlewareClass.name}:`, error)
				}
			}
		} else {
			for (const [middlewareName, MiddlewareClass] of Object.entries(middlewares)) {
				if (typeof MiddlewareClass === 'function' && middlewareName !== 'default') {
					try {
						const middlewareInstance = container.resolve(MiddlewareClass) as Middleware
						resolved.push(middlewareInstance)
					} catch (error) {
						console.warn(`Failed to resolve middleware ${middlewareName}:`, error)
					}
				}
			}
		}

		return resolved
	}
}

package handlers

import (
	"context"
	"fmt"

	"template/api-go/internal/sync/entities"
	"template/api-go/internal/sync/events"
	"template/core-go/types"
)

// adSetStorage is the minimal interface the handler uses.
// Satisfied by storage/adset.PgAdSetStorage.
type adSetStorage interface {
	InputChannel() chan<- []*entities.AdSet
}

// AdSetUpdatedHandler consumes ExternalAdSetUpdatedEvent, rebuilds
// the canonical AdSet from the normalised provider input, and enqueues it
// on the storage's input channel for async persistence.
type AdSetUpdatedHandler struct {
	storage adSetStorage
}

// NewAdSetUpdatedHandler wires the handler with its storage dependency.
func NewAdSetUpdatedHandler(storage adSetStorage) *AdSetUpdatedHandler {
	return &AdSetUpdatedHandler{storage: storage}
}

// EventName returns the event name this handler listens on.
func (h *AdSetUpdatedHandler) EventName() string {
	return events.ExternalAdSetUpdatedEventName
}

// Handle rebuilds the canonical AdSet aggregate from the normalised input
// and enqueues it on the storage input channel.
func (h *AdSetUpdatedHandler) Handle(ctx context.Context, event types.DomainEventI) error {
	evt, ok := event.(events.ExternalAdSetUpdatedEvent)
	if !ok {
		return fmt.Errorf("ad_set handler: unexpected event type %T (want ExternalAdSetUpdatedEvent)", event)
	}

	as, err := entities.NewAdSetFromProviderPayload(evt.Payload.Input)
	if err != nil {
		return fmt.Errorf("ad_set handler: rebuild aggregate: %w", err)
	}

	select {
	case h.storage.InputChannel() <- []*entities.AdSet{as}:
	case <-ctx.Done():
		return ctx.Err()
	}

	return nil
}

package handlers

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"

	coreerrors "template/core-go/errors"
	ctxerrors "template/api-go/internal/sync/errors"
	"template/api-go/internal/sync/enums"
	"template/api-go/internal/sync/services/credentials"
	"template/api-go/internal/sync/services/pipelineresolver"
	"template/contracts-go/wire"
	"template/core-go/types"
)

// StartSyncArgs decouples the handler from the concrete StartSync use case (testable).
type StartSyncArgs struct {
	StoreID                    string
	StoreIntegrationID         string
	StoreIntegrationExternalID string
	Platform                   wire.Platform
	Pipelines                  []enums.SyncPipelineName
}

// SyncStarter is satisfied by an adapter over usecases.StartSync.
type SyncStarter interface {
	Start(ctx context.Context, in StartSyncArgs) (jobID string, err error)
}

// AsyncExecutor is satisfied by executor.Executor.ExecuteAsync.
type AsyncExecutor interface {
	ExecuteAsync(ctx context.Context, jobID string, creds map[string]string) error
}

// IntegrationActivatedHandler consumes integration.activated and auto-starts a sync.
type IntegrationActivatedHandler struct {
	starter   SyncStarter
	exec      AsyncExecutor
	exchanger credentials.Exchanger
}

func NewIntegrationActivatedHandler(s SyncStarter, e AsyncExecutor, x credentials.Exchanger) *IntegrationActivatedHandler {
	return &IntegrationActivatedHandler{starter: s, exec: e, exchanger: x}
}

func (h *IntegrationActivatedHandler) EventName() string {
	return wire.IntegrationActivatedIntegrationEventName
}

func (h *IntegrationActivatedHandler) Handle(ctx context.Context, event types.IntegrationEventI) error {
	decoded, err := decodeActivated(event)
	if err != nil {
		return err
	}

	pipelines := pipelineresolver.Resolve(decoded.Type)
	if len(pipelines) == 0 {
		slog.Info("integration.activated: no pipelines for type, skipping", "type", decoded.Type)
		return nil
	}

	creds, err := h.exchanger.Exchange(ctx, decoded.CredentialHandle)
	if err != nil {
		return err
	}

	jobID, err := h.starter.Start(ctx, StartSyncArgs{
		StoreID:                    decoded.StoreID,
		StoreIntegrationID:         decoded.StoreIntegrationID,
		StoreIntegrationExternalID: decoded.StoreIntegrationExternalID,
		Platform:                   decoded.Platform,
		Pipelines:                  pipelines,
	})
	if err != nil {
		// SYNC_ALREADY_RUNNING is the idempotency guard for redelivered events — absorb it.
		if isAlreadyRunning(err) {
			slog.Info("integration.activated: sync already running, idempotent skip", "integrationId", decoded.StoreIntegrationID)
			return nil
		}
		return err
	}

	// Detached: a backfill must not block the consumer goroutine.
	go func() {
		if err := h.exec.ExecuteAsync(context.WithoutCancel(ctx), jobID, creds); err != nil {
			slog.Error("integration.activated: ExecuteAsync failed", "jobId", jobID, "error", err)
		}
	}()
	return nil
}

func decodeActivated(event types.IntegrationEventI) (wire.IntegrationActivatedIntegrationEvent, error) {
	provider, ok := event.(interface{ GetPayload() json.RawMessage })
	if !ok {
		return wire.IntegrationActivatedIntegrationEvent{}, fmt.Errorf("event %s carries no payload", event.GetEventName())
	}
	decoded, err := wire.UnmarshalIntegrationEvent(provider.GetPayload())
	if err != nil {
		return wire.IntegrationActivatedIntegrationEvent{}, err
	}
	v, ok := decoded.(wire.IntegrationActivatedIntegrationEvent)
	if !ok {
		return wire.IntegrationActivatedIntegrationEvent{}, fmt.Errorf("unexpected event type %T", decoded)
	}
	return v, nil
}

func isAlreadyRunning(err error) bool {
	var ae *coreerrors.AppError
	return errors.As(err, &ae) && ae.Code == ctxerrors.CodeSyncAlreadyRunning
}

