@injectable()
export class DrizzleOrderOverrideRepository extends OrderOverrideRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findByPin(orderId: string, storeIntegrationExternalId: string, tx?: DrizzleClient): Promise<OrderOverride | undefined> {
		const dbClient = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbClient
				.select()
				.from(orderOverrides)
				.where(and(eq(orderOverrides.orderId, orderId), eq(orderOverrides.storeIntegrationExternalId, storeIntegrationExternalId)))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: OrderOverride, tx?: DrizzleClient): Promise<OrderOverride> {
		entity.incrementVersion()
		const dbClient = tx ?? this.db
		const data = this.toPersistence(entity)
		const result = await tryCatchAsync(async () => {
			await dbClient
				.insert(orderOverrides)
				.values(data)
				.onConflictDoUpdate({
					target: [orderOverrides.orderId, orderOverrides.storeIntegrationExternalId],
					set: {
						paymentMethod: data.paymentMethod,
						paymentStatus: data.paymentStatus,
						revenueAmountCents: data.revenueAmountCents,
						revenueCurrency: data.revenueCurrency,
						shippingAmountCents: data.shippingAmountCents,
						shippingCurrency: data.shippingCurrency,
						feesAmountCents: data.feesAmountCents,
						feesCurrency: data.feesCurrency,
						taxesAmountCents: data.taxesAmountCents,
						taxesCurrency: data.taxesCurrency,
						productCostByLine: data.productCostByLine,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbClient = tx ?? this.db
		await tryCatchAsync(async () => {
			await dbClient.delete(orderOverrides).where(eq(orderOverrides.orderId, id))
		})
	}

	private toDomain(row: typeof orderOverrides.$inferSelect): OrderOverride {
		const productCostByLine = row.productCostByLine
			? (row.productCostByLine as Array<{ lineId: string; costAmountCents: number; costCurrency: string }>).map(e => ({
					lineId: e.lineId,
					cost: { amountCents: e.costAmountCents, currency: e.costCurrency },
				}))
			: undefined
		const fields = OrderOverrideFieldsSchema.parse({
			paymentMethod: row.paymentMethod ?? undefined,
			paymentStatus: row.paymentStatus ?? undefined,
			revenue:
				row.revenueAmountCents != null && row.revenueCurrency
					? { amountCents: Number(row.revenueAmountCents), currency: row.revenueCurrency }

