      const existing = await this.overrides.findByPin(orderId, externalId, tx)

      // 2. Call behavior methods (entity validates)
      existing.mergeFields(input.patch)

      // 3. Persist entity + events in same TX
      await this.overrides.save(existing, tx)
      await this.domainEventRepository.save(
        new OrderOverriddenEvent({...}),
