// Auth middleware (example)
@injectable()
export class AuthAccountMiddleware extends Middleware {
  constructor(private sessionRepo: SessionRepository) { super() }

  async execute(request: HttpControllerRequest<unknown>): Promise<HttpMiddlewareResponse<unknown>> {
    const session = await this.sessionRepo.findBySession(request.cookie.session)
    if (!session) {
      return { status: HttpStatusCode.UNAUTHORIZED }  // Short-circuit; don't call handler
    }
    request.ctx.user = { id: session.userId, name: session.userName }
    request.ctx.session = session
    return { status: undefined }  // Continue to next middleware
  }
}

