  internalHandlers,         // Record<string, EventHandler>
  externalHandlers,         // Record<string, EventHandler>
  registry: INSTANCE_REGISTRY,  // { mock, integration, real }
})

export default ctx.router
```

This does:
1. Create a child DI container (or root if `root: true`)
2. Register all bindings from `INSTANCE_REGISTRY.real` (or mock/integration in tests)
3. Instantiate and register all controllers via `container.resolve(ControllerClass)`
4. Register handlers with `InternalMediator` + `ExternalMediator`
5. Register projectors with `InternalMediator`
6. Return a router that services HTTP requests

**Spring Boot equivalent:**
```java
@SpringBootApplication
@ComponentScan(basePackages = {
  "com.app.sales",
  "com.app.integration",
  "com.app.shared"
})
public class ApiApplication {
  public static void main(String[] args) {
    SpringApplication.run(ApiApplication.class, args);
  }
}

// Implicit:
// 1. `ApplicationContext` created (singleton DI container)
// 2. @Configuration classes scanned; @Bean methods invoked
// 3. @RestController classes auto-wired; endpoints registered
// 4. @Component / @Service / @Repository beans instantiated
// 5. Handlers (@EventListener) registered with ApplicationEventPublisher
```

### 12. TRANSACTION BOUNDARY & UNIT OF WORK

**TypeScript:**
```typescript
protected async withTransaction<T>(tx?: Transaction, fn: (tx: T) => Promise<T>): Promise<T> {
  if (tx) return fn(tx)  // Already in TX (nested call)
  const uow = this.unitOfWorkFactory.create()  // InjectedDependency
  return uow.transaction(async newTx => fn(newTx as Tx))
}

// Use case body:
protected async handle(input, tx?) {
  return this.withTransaction(tx, async tx => {
    const entity = await repo.findById(id, tx)  // Pass TX down
    entity.mergeFields(input.patch)
    await repo.save(entity, tx)  // Same TX
    await domainEventRepository.save(event, tx)  // Same TX
    return { ... }
  })  // <- TX commits here
}
```

**Spring equivalent:**
```java
@Service
@Transactional(propagation = Propagation.REQUIRED)  // Implicit UoW
public class UpdateOrderOverride {
  private final OrderOverrideRepository repo;
  private final DomainEventRepository domainEventRepo;

  public UpdateOrderOverrideOutput execute(UpdateOrderOverrideInput input) {
    var entity = repo.findById(input.orderId()).orElse(null);
    entity.mergeFields(input.patch());
    repo.save(entity);  // EntityManager queues
    domainEventRepo.save(event);  // EntityManager queues
    return new UpdateOrderOverrideOutput(...);
    // TX commits here; all changes flushed
  }
}
```

**Key parallel:**
- TypeScript: `UnitOfWorkFactory.create()` → `UnitOfWork.transaction(fn)` → pass `Transaction` to repos
- Spring: `@Transactional` AOP → `EntityManager` (thread-local) → implicit in repo calls

### 13. OUTBOX & EVENT DISPATCH

**Outbox pattern (both services):**

| Component | TypeScript | Spring Boot |
|---|---|---|
| **Outbox table** | `outbox (id, name, payload, processed_at, attempts)` | Same schema |
| **Dispatcher** | `OutboxDispatcher` (background poll via `CommandQueue`) | `@Scheduled(fixedDelay)` method |
| **Fan-out** | `InternalMediator.dispatch(event)` | `ApplicationEventPublisher.publishEvent()` |
| **Retry** | Outbox row stays unprocessed; retried by dispatcher | `@Retryable` on handler |

### 14. COMPLETE DEPENDENCY TREE

```
HTTP Request
  │
  ├─ Router.resolve(ControllerClass)
  │   └─ container.resolve(ControllerClass)
  │
  ├─ ControllerInstance.executeController(request)
  │   │ (runs middlewares)
  │   └─ ControllerInstance.execute(request)
  │       └─ ControllerInstance.handle(request)
  │           │ (typed request)
  │           └─ UseCase.execute(input)
  │               │
  │               ├─ UnitOfWorkFactory.create()
  │               │   └─ UnitOfWork.transaction(async tx => {
  │               │       ├─ Repository.findById(id, tx)
  │               │       ├─ Entity.mergeFields()
  │               │       ├─ Repository.save(entity, tx)
  │               │       └─ DomainEventRepository.save(event, tx)
  │               │
  │               └─ (TX commits)
  │                   └─ OutboxDispatcher polls
  │                       └─ InternalMediator.dispatch(event)
  │                           ├─ EventHandler.handle()
  │                           │   └─ ExternalMediator.publish(integrationEvent)
  │                           │       └─ Kafka
  │                           │
  │                           └─ Projector.handle(event)
  │                               └─ ProjectionRepository.save(projection)
```

### 15. TESTING INFRASTRUCTURE

| Mode | TypeScript | Spring Boot | Use Case |
|---|---|---|---|
| **Unit** | Direct entity instantiation; no TestBed | `@Test` with entity constructor | Entity invariants |
| **Integration** | `TestBed.create('integration')` with `PGliteDriver` | `@SpringBootTest` + `@DataJpaTest` | Repository + UoW |
| **Flow** | `TestBed.create('mock')` with `MockExternalMediator` | `@SpringBootTest` with mocked externals | End-to-end command |
| **E2E** | Same process; real HTTP server | `@SpringBootTest(webEnvironment = RANDOM_PORT)` | Full stack |

---

## Summary: Key Concrete Names for Spring Migration

**Framework layer:**
- `@injectable()` ↔ `@Component` / `@Service` / `@Repository`
- `tsyringe-neo` container ↔ Spring `ApplicationContext`
- `BoundedContext.create({controllers, handlers, registry})` ↔ `@SpringBootApplication` + `@Configuration`

**Domain layer:**
- `class X extends AggregateRoot<Schema>` ↔ `@Entity class X`
- `static schema = z.object(...)` ↔ `@Column` + `@Embedded` annotations
- `protected addDomainEvent()` ↔ `domainEventPublisher.publishEvent()`
- `class X extends Handler<InputSchema, OutputSchema>` ↔ `@Service public class X`

**Persistence layer:**
- `abstract Repository<T> { save(entity, tx?); findById(id, tx?) }` ↔ `extends JpaRepository<T, ID>`
- `DrizzleXRepository` ↔ `@Repository class XRepositoryImpl`
- `MockXRepository` ↔ Testcontainers or H2 in-memory

**Event layer:**
- `class OrderOverriddenEvent extends BaseDomainEvent` ↔ `extends ApplicationEvent`
- `EventHandler<E>` ↔ `@EventListener` + `@Async`
- `ExternalMediator.publish()` ↔ `KafkaTemplate.send()`
- `OutboxDispatcher` ↔ `@Scheduled` + `@Transactional`

**HTTP layer:**
- `Controller.path`, `Controller.method` ↔ `@GetMapping`, `@PostMapping`, etc.
- `InputSchema` / `OutputSchema` ↔ `@RequestBody` + `@Valid`
- `override middlewares` ↔ `@Bean WebMvcConfigurer.addInterceptors()`

This codebase is a **textbook DDD + Clean Architecture implementation** with first-class event sourcing, making the Spring Boot translation straightforward — each TypeScript primitive maps 1:1 to Spring's annotation-driven equivalents.

