#### **Handler/Worker Structure** (internal/sync/handlers/ad_set_updated_handler.go)

```go
type AdSetUpdatedHandler struct {
    storage adSetStorage  // Interface, not concrete (testable)
}

func (h *AdSetUpdatedHandler) EventName() string {
    return events.ExternalAdSetUpdatedEventName
}

func (h *AdSetUpdatedHandler) Handle(ctx context.Context, event types.DomainEventI) error {
    evt, ok := event.(events.ExternalAdSetUpdatedEvent)
    if !ok {
        return fmt.Errorf("unexpected event type %T", event)
    }

    // Rebuild aggregate from normalized provider input
    as, err := entities.NewAdSetFromProviderPayload(evt.Payload.Input)
    if err != nil {
        return err
    }

    // Enqueue for async persistence (non-blocking)
    select {
    case h.storage.InputChannel() <- []*entities.AdSet{as}:
    case <-ctx.Done():
