#### **net/http Routing** (core/services/httprouter/http_router.go)

```go
type HttpRouter struct {
    mux         *http.ServeMux
    version     string
    middlewares []types.Middleware
}

// RegisterControllers reads controller metadata and auto-routes
func (r *HttpRouter) RegisterControllers(controllers []types.Controller) {
    for _, c := range controllers {
        meta := c.Metadata()

        // Build pattern: /api/{version}/{context}/{path}
        fullPath := "/api/" + r.version
        if meta.Context != "" {
            fullPath += "/" + meta.Context
        }
        fullPath += meta.Path

        pattern := meta.Method + " " + fullPath  // "POST /api/v1/sync/jobs"

        var handler http.Handler = http.HandlerFunc(c.Handle)

        // Apply middlewares (innermost first, then global)
        for i := len(meta.Middlewares) - 1; i >= 0; i-- {
            handler = meta.Middlewares[i](handler)
        }
        for i := len(r.middlewares) - 1; i >= 0; i-- {
            handler = r.middlewares[i](handler)
        }

        r.mux.Handle(pattern, handler)
    }
}
```

**Controller definition** (core/types/controller.go):
```go
type Controller interface {
    Metadata() ControllerMetadata
    Handle(w http.ResponseWriter, r *http.Request)
}

type ControllerMetadata struct {
    Context     string        // "sync", "integrations", "" for shared
    Path        string        // "/jobs", "/{id}/execute"
    Method      string        // "POST", "GET"
    Description string
    Request     any           // Zero value of request struct (for OpenAPI emission)
    Response    any           // Zero value of response struct
    Status      int           // Custom success code (0 defaults to 200/204)
    Errors      []errors.ErrorCode
    Middlewares []types.Middleware
}
```

**Concrete controller example** (internal/sync/controllers/sync_controller.go):
```go
type SyncController struct {
    startSync   *usecases.StartSync
    executeSync *usecases.ExecuteSync
}

func (c *SyncController) Metadata() types.ControllerMetadata {
    return types.ControllerMetadata{
        Context:     "sync",
        Path:        "/sync",
        Method:      http.MethodPost,
        Description: "Run all registered pipelines for a platform synchronously",
        Request:     syncRequest{},      // Zod-equivalent validation struct
        Response:    syncResponse{},
    }
}

func (c *SyncController) Handle(w http.ResponseWriter, r *http.Request) {
    req, err := httputil.DecodeRequest[syncRequest](r)
    if err != nil {
        httputil.RespondError(w, err)
        return
    }

    startOut, err := c.startSync.Execute(r.Context(), usecases.StartSyncInput{...})
    if err != nil {
        httputil.RespondError(w, err)
        return
    }

    httputil.RespondJSON(w, http.StatusOK, syncResponse{...})
}
```

**Routing semantics:**
- Routes are declared **in code** (no separate routing file); metadata is declarative.
- Pattern is `"METHOD /api/{version}/{context}{path}"` — `net/http` 1.22+ supports method+pattern strings natively.
- OpenAPI spec is **generated from controller metadata** — no swag annotations (unlike older Go patterns).
- Middleware is a `func(http.Handler) http.Handler` chain; both controller-local and global.

