#### **sqlc Usage** (internal/sync/repositories/syncjob/syncjob_pg.go)

Go uses **raw SQL** (not sqlc ORM in this codebase — no `sqlc.yaml`), with direct `database/sql` + manual scanning:

```go
type PgSyncJobRepository struct {
    db *sql.DB
}

const upsertSQL = `
INSERT INTO sync_jobs (id, store_id, store_integration_id, platform, pipelines, status, ...)
VALUES ($1,$2,$3,$4,$5,$6,...)
ON CONFLICT (id) DO UPDATE SET
  status = EXCLUDED.status, pipelines = EXCLUDED.pipelines, ...`

func (r *PgSyncJobRepository) Save(ctx context.Context, j *entities.SyncJob) error {
    pipelines, err := json.Marshal(j.Pipelines)
    if err != nil {
        return err
    }
    _, err = r.querier(ctx).ExecContext(ctx, upsertSQL,
        j.ID.UUID(), j.StoreID.UUID(), j.StoreIntegrationID.UUID(), j.Platform,
        pipelines, string(j.Status), j.WindowStart, j.WindowEnd, ...)
    return err
}

func (r *PgSyncJobRepository) FindByID(ctx context.Context, id objects.ID) (*entities.SyncJob, error) {
    row := r.querier(ctx).QueryRowContext(ctx, 
        `SELECT id, store_id, ... FROM sync_jobs WHERE id = $1`, id.UUID())
    return scanJob(row)
}

// querier returns tx from UnitOfWork context, else the connection pool
func (r *PgSyncJobRepository) querier(ctx context.Context) interface {
    ExecContext(context.Context, string, ...any) (sql.Result, error)
    QueryRowContext(context.Context, string, ...any) *sql.Row
    QueryContext(context.Context, string, ...any) (*sql.Rows, error)
} {
    if tx, ok := unitofwork.TxFromContext(ctx); ok {
        return tx
    }
    return r.db
}
```

**sqlc note:** The codebase doesn't use sqlc generators; queries are hand-written with type-safe scanning. This gives explicit control but no code generation. (sqlc would eliminate the `scanJob` boilerplate.)

